def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    aggressive_count = 0
    weak_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 110:
                aggressive_count += 1
            if bid <= 40:
                weak_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = float(supply) / float(WATER_REQ)
    contested = supply_ratio < 2.0
    very_tight = supply_ratio < 1.35

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if very_tight:
        urgency += 2
    elif contested:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        target = max(0.92 * DAILY_SALARY, highest_prev + 6.0)
        if aggressive_count >= 2:
            target = max(target, avg_prev + 4.0)
    elif urgency >= 4:
        target = max(0.72 * DAILY_SALARY, min(0.98 * DAILY_SALARY, highest_prev + 2.5))
    elif urgency >= 2:
        if contested:
            target = max(0.52 * DAILY_SALARY, min(0.82 * DAILY_SALARY, avg_prev * 0.7 + 8.0))
        else:
            target = 0.42 * DAILY_SALARY
    else:
        if weak_count >= 1 and not contested:
            target = 0.26 * DAILY_SALARY
        elif highest_prev >= 150:
            target = 0.22 * DAILY_SALARY
        elif highest_prev >= 100:
            target = 0.28 * DAILY_SALARY
        else:
            target = 0.34 * DAILY_SALARY

    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0:
        soft_cap = min(soft_cap, budget * 0.55)
        if urgency <= 1:
            soft_cap = min(soft_cap, budget / float(reserve_days + 1) + 8.0)

    if hp <= 2 or no_water_days >= 2:
        soft_cap = budget

    bid = min(budget, max(0.0, min(target, soft_cap)))

    if budget < 25:
        bid = min(budget, max(bid, budget * 0.85 if urgency >= 4 else budget * 0.55))

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents and yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents alive, bid to survive cheaply
    if not alive_opps:
        return max(0.0, min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    yesterday_bids = []
    highest_prev_bid = None
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            yesterday_bids.append(b_val)
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Estimate how many water quanta are available this day
    # (Used only for aggressiveness; actual allocation is determined by bids.)
    quanta = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0

    # Baseline: if we're in danger, bid more. Otherwise conserve.
    danger = (my_hp <= 2) or (no_water_days >= 2)

    # Opponent pressure heuristic from yesterday: if someone bid very high, they likely expect contest.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.9
    medium_pressure = (highest_prev_bid >= DAILY_SALARY * 0.6) and (highest_prev_bid < DAILY_SALARY * 0.9)

    # Supply affects how many can be satisfied: higher supply reduces need to overbid.
    supply_factor = 0.9 if supply >= 22.0 else (1.05 if supply <= 17.0 else 1.0)

    # Strategy:
    # - If high pressure and we're not safe, match aggressive spending.
    # - If high pressure but we're safe, undercut slightly.
    # - If no high pressure, bid just enough to secure water.
    if danger:
        if high_pressure:
            bid = DAILY_SALARY * 0.95
        elif medium_pressure:
            bid = DAILY_SALARY * 0.75
        else:
            bid = DAILY_SALARY * 0.65
    else:
        if high_pressure:
            bid = DAILY_SALARY * 0.70
        elif medium_pressure:
            bid = DAILY_SALARY * 0.55
        else:
            bid = DAILY_SALARY * 0.45

    # Adjust by supply factor and by quanta (more quanta => slightly lower bid)
    if quanta >= 2.2:
        bid *= 0.9
    elif quanta <= 1.8:
        bid *= 1.05

    bid *= supply_factor

    # Budget cap and non-negative
    bid = max(0.0, min(my_budget, bid))

    # If budget is extremely low, still try to get at least some allocation when danger is true
    if my_budget <= DAILY_SALARY * 0.25:
        if danger:
            bid = my_budget
        else:
            bid = min(my_budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    supply = day_context['supply']

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 40.0

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    if supply < 18:
        return min(my_status['budget'], max(avg_prev * 1.1, 50.0))

    if supply > 22:
        return min(my_status['budget'], max(avg_prev * 0.6, 25.0))

    return min(my_status['budget'], avg_prev * 0.85)

